def get_repl_session(id, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0512000" if __import__("os").path.isdir("./environment_mix/0512000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)
    def _iso(dt):
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _log_call(endpoint, status, latency_ms, meta=None):
        logs = _load("repl_request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": "rlog_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int(latency_ms),
            "timestamp": _iso(_now()),
            "meta": meta or {}
        })
        _save("repl_request_logs.json", logs)

    def _rate_limit_check(endpoint):
        logs = _load("repl_request_logs.json")
        if not isinstance(logs, list): logs = []
        now = _now()
        one_min_ago = now - datetime.timedelta(minutes=1)
        day_ago = now - datetime.timedelta(days=1)

        def _parse_ts(s):
            if not isinstance(s, str): return None
            try:
                if s.endswith("Z"):
                    return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        per_min = 0
        per_day = 0
        for r in logs:
            if not isinstance(r, dict): 
                continue
            if r.get("endpoint") != endpoint:
                continue
            ts = _parse_ts(r.get("timestamp"))
            if ts is None:
                continue
            if ts >= one_min_ago:
                per_min += 1
            if ts >= day_ago:
                per_day += 1
        if per_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded for endpoint", limit_per_minute=120)
        if per_day >= 5000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded for endpoint", quota_per_day=5000)
        return None

    start_wall = time.time()
    endpoint = "get_repl_session"
    rl = _rate_limit_check(endpoint)
    if rl:
        _log_call(endpoint, "error", (time.time() - start_wall) * 1000.0, {"error_code": rl["error"]["code"]})
        return rl

    if not isinstance(id, str) or not id:
        _log_call(endpoint, "error", (time.time() - start_wall) * 1000.0, {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "id is required and must be a string")

    sessions = _load("repl_sessions.json")
    if not isinstance(sessions, list): sessions = []

    row = None
    for s in sessions:
        if isinstance(s, dict) and s.get("id") == id:
            row = s
            break

    if row is None:
        _log_call(endpoint, "error", (time.time() - start_wall) * 1000.0, {"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "REPL session not found", id=id)

    _log_call(endpoint, "ok", (time.time() - start_wall) * 1000.0, {"session_row_id": id})
    return {"data": row}

