        if not isinstance(logs, list): logs = []
        now = _now()
        one_min_ago = now - datetime.timedelta(minutes=1)
        day_ago = now - datetime.timedelta(days=1)

        def _parse_ts(s):
            if not isinstance(s, str): return None
            try:
                if s.endswith("Z"):
                    return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        per_min = 0
        per_day = 0
        for r in logs:
            if not isinstance(r, dict): 
                continue
            if r.get("endpoint") != endpoint:
                continue
            ts = _parse_ts(r.get("timestamp"))
            if ts is None:
                continue
            if ts >= one_min_ago:
                per_min += 1
            if ts >= day_ago:
                per_day += 1
        if per_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded for endpoint", limit_per_minute=120)
        if per_day >= 5000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded for endpoint", quota_per_day=5000)
        return None

    start_wall = time.time()
    endpoint = "list_repl_sessions"
    rl = _rate_limit_check(endpoint)
    if rl:
        _log_call(endpoint, "error", (time.time() - start_wall) * 1000.0, {"error_code": rl["error"]["code"]})
        return rl

    if session_id is not None and (not isinstance(session_id, str) or not session_id):
        _log_call(endpoint, "error", (time.time() - start_wall) * 1000.0, {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "session_id must be a non-empty string when provided")
    if status is not None:
        if not isinstance(status, str):
            _log_call(endpoint, "error", (time.time() - start_wall) * 1000.0, {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ("active", "idle", "closed", "error"):
            _log_call(endpoint, "error", (time.time() - start_wall) * 1000.0, {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid status filter", allowed=["active", "idle", "closed", "error"])
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log_call(endpoint, "error", (time.time() - start_wall) * 1000.0, {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

    # cursor: base64 encoded integer offset
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            _log_call(endpoint, "error", (time.time() - start_wall) * 1000.0, {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            offset = int(raw)
            if offset < 0:
                raise ValueError("negative")
        except Exception:
            _log_call(endpoint, "error", (time.time() - start_wall) * 1000.0, {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid cursor")

    sessions = _load("repl_sessions.json")
    if not isinstance(sessions, list): sessions = []

    def _parse_dt(s):
        if not isinstance(s, str): return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    rows = []
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if session_id is not None and s.get("session_id") != session_id:
            continue
        if status is not None and s.get("status") != status:
            continue
        rows.append(s)

    # order by most recent activity: last_activity_at desc, then updated_at desc, then created_at desc
    def _key(s):
        la = _parse_dt(s.get("last_activity_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        ua = _parse_dt(s.get("updated_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        ca = _parse_dt(s.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        return (la, ua, ca)

    rows.sort(key=_key, reverse=True)

    total = len(rows)
    page = rows[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("utf-8") if has_more else None

    _log_call(endpoint, "ok", (time.time() - start_wall) * 1000.0, {"returned": len(page), "total": total})
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def update_repl_session(id, status=None, close_reason=None, closed_at=None, last_activity_at=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0512000" if __import__("os").path.isdir("./environment_mix/0512000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                d = json.load(f)
                return d if isinstance(d, list) else []
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _append_request_log(endpoint, status_s, latency_ms, meta=None):
        logs = _load("repl_request_logs.json")
        logs.append({
            "id": "rlog_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status_s,
            "latency_ms": int(latency_ms),
            "timestamp": _iso(_now()),
            "meta": meta or {}
        })
        _save("repl_request_logs.json", logs)

    def _enforce_limits(endpoint):
        logs = _load("repl_request_logs.json")
        now = _now()
        one_min_ago = now - datetime.timedelta(minutes=1)
        day_ago = now - datetime.timedelta(days=1)

        def _parse_ts(s):
            if not isinstance(s, str) or not s:
                return None
            try:
                if s.endswith("Z"):
                    return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        per_min = 0
        per_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != endpoint:
                continue
            ts = _parse_ts(r.get("timestamp"))
            if ts is None:
                continue
            if ts >= one_min_ago:
                per_min += 1
            if ts >= day_ago:
                per_day += 1

        if per_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.", limit_per_minute=120, endpoint=endpoint)
        if per_day >= 5000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", limit_per_day=5000, endpoint=endpoint)
        return None

    endpoint = "update_repl_session"
    t0 = time.time()

    if not isinstance(id, str) or not id.strip():
        err = _err("VALIDATION_ERROR", "Parameter 'id' must be a non-empty string.")
        _append_request_log(endpoint, "error", (time.time() - t0) * 1000, {"error": err["error"]})
        return err

    if status is not None:
        if not isinstance(status, str):
            err = _err("VALIDATION_ERROR", "Parameter 'status' must be a string.")
            _append_request_log(endpoint, "error", (time.time() - t0) * 1000, {"error": err["error"]})
            return err
        if status not in ("active", "idle", "closed", "error"):
            err = _err("VALIDATION_ERROR", "Parameter 'status' must be one of: active, idle, closed, error.")
            _append_request_log(endpoint, "error", (time.time() - t0) * 1000, {"error": err["error"]})
            return err

    if close_reason is not None and not isinstance(close_reason, str):
        err = _err("VALIDATION_ERROR", "Parameter 'close_reason' must be a string when provided.")
        _append_request_log(endpoint, "error", (time.time() - t0) * 1000, {"error": err["error"]})
        return err

    if closed_at is not None and _parse_dt(closed_at) is None:
        err = _err("VALIDATION_ERROR", "Parameter 'closed_at' must be an ISO8601 datetime string when provided.")
        _append_request_log(endpoint, "error", (time.time() - t0) * 1000, {"error": err["error"]})
        return err

    if last_activity_at is not None and _parse_dt(last_activity_at) is None:
        err = _err("VALIDATION_ERROR", "Parameter 'last_activity_at' must be an ISO8601 datetime string when provided.")
        _append_request_log(endpoint, "error", (time.time() - t0) * 1000, {"error": err["error"]})
        return err

    lim_err = _enforce_limits(endpoint)
    if lim_err:
        _append_request_log(endpoint, "error", (time.time() - t0) * 1000, {"error": lim_err["error"]})
        return lim_err

    sessions = _load("repl_sessions.json")
    row = next((r for r in sessions if isinstance(r, dict) and r.get("id") == id), None)
    if row is None:
        err = _err("NOT_FOUND", "Session not found.", id=id)
        _append_request_log(endpoint, "error", (time.time() - t0) * 1000, {"error": err["error"]})
        return err

    # Allowed transitions per schema
    transitions = {
        "active": set(["idle", "closed", "error"]),
        "idle": set(["active", "closed", "error"]),
        "error": set(["closed"]),
        "closed": set([]),
    }

    # Apply status transition if requested
    if status is not None:
        cur = row.get("status")
        if cur != status:
            allowed = transitions.get(cur, set())
            if status not in allowed:
                err = _err(
                    "INVALID_TRANSITION",
                    "Invalid session status transition by lifecycle rule.",
                    from_status=cur,
                    to_status=status,
                    rule="repl_sessions.lifecycle.transitions"
                )
                _append_request_log(endpoint, "error", (time.time() - t0) * 1000, {"error": err["error"]})
                return err
            row["status"] = status

    # Mutables: last_activity_at can be set anytime
    if last_activity_at is not None:
        row["last_activity_at"] = last_activity_at

    # Closing rules
    if row.get("status") == "closed":
        # closed_at must be set (server can default)
        if closed_at is not None:
            row["closed_at"] = closed_at
        elif row.get("closed_at") in (None, ""):
            row["closed_at"] = _iso(_now())
        # close_reason accepted when closed
        if close_reason is not None:
            row["close_reason"] = close_reason
        elif row.get("close_reason") is None:
            # leave as-is; no forced reason
            row["close_reason"] = row.get("close_reason")
    else:
        # Constraint: closed_at is null unless status='closed'
        if closed_at is not None:
            err = _err("VALIDATION_ERROR", "closed_at may only be set when status is 'closed'.", status=row.get("status"))
            _append_request_log(endpoint, "error", (time.time() - t0) * 1000, {"error": err["error"]})
            return err
        # If user sends close_reason while not closed, reject (schema says accepted when status set to closed)
        if close_reason is not None:
            err = _err("VALIDATION_ERROR", "close_reason is only accepted when status is set to 'closed'.", status=row.get("status"))
            _append_request_log(endpoint, "error", (time.time() - t0) * 1000, {"error": err["error"]})
            return err
        # ensure closed fields cleared
        row["closed_at"] = None
        row["close_reason"] = None

    # Constraint: status='error' implies last_activity_at not null
    if row.get("status") == "error" and not row.get("last_activity_at"):
        # If caller didn't provide last_activity_at, set it to now (server-side repair)
        row["last_activity_at"] = _iso(_now())

    row["updated_at"] = _iso(_now())
    _save("repl_sessions.json", sessions)

    _append_request_log(endpoint, "ok", (time.time() - t0) * 1000, {"id": id})

    return {"object": "repl_session", "data": row}

