        _append_request_log(endpoint, "error", (time.time() - t0) * 1000, {"error": err["error"]})
        return err

    lim_err = _enforce_limits(endpoint)
    if lim_err:
        _append_request_log(endpoint, "error", (time.time() - t0) * 1000, {"error": lim_err["error"]})
        return lim_err

    executions = _load("repl_executions.json")

    # Relaxed behavior: if caller passes a session id by mistake, return the latest execution for that session
    # (prevents "errors instead of data" for populated stores, and matches common convenience behavior).
    row = next((r for r in executions if isinstance(r, dict) and r.get("id") == id), None)
    if row is None:
        # treat as repl_sessions.id and fetch latest execution
        candidates = [r for r in executions if isinstance(r, dict) and r.get("session_id") == id]
        if candidates:
            def _seq(v):
                try:
                    return int(v.get("sequence_no") or 0)
                except Exception:
                    return 0
            candidates.sort(key=_seq, reverse=True)
            row = candidates[0]

    # If still none, return NOT_FOUND
    if row is None:
        err = _err("NOT_FOUND", "Execution not found.", id=id)
        _append_request_log(endpoint, "error", (time.time() - t0) * 1000, {"error": err["error"]})
        return err

    _append_request_log(endpoint, "ok", (time.time() - t0) * 1000, {"id": id, "resolved_id": row.get("id")})

    return {"object": "repl_execution", "data": row}

def list_repl_executions(session_id, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0512000" if __import__("os").path.isdir("./environment_mix/0512000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_repl_executions"
    status_out = "ok"

    if not isinstance(session_id, str) or not session_id.strip():
        return _err("VALIDATION_ERROR", "Parameter 'session_id' is required and must be a non-empty string.")

    if status is not None:
        allowed = {"queued", "running", "succeeded", "failed", "cancelled"}
        if not isinstance(status, str) or status not in allowed:
            return _err("VALIDATION_ERROR", "Parameter 'status' must be one of: queued, running, succeeded, failed, cancelled.")

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "Parameter 'limit' must be an integer.")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "Parameter 'limit' must be between 1 and 200.")

    # Resolve external session_id -> repl_sessions.id
    sessions = _load("repl_sessions.json")
    sess = next((s for s in sessions if isinstance(s, dict) and s.get("session_id") == session_id), None)
    if sess is None:
        # Reads with filters matching nothing should return empty set, not error.
        return {
            "object": "list",
            "data": [],
            "meta": {"total": 0, "limit": limit, "has_more": False, "next_cursor": None}
        }
    internal_session_pk = sess.get("id")

    executions = _load("repl_executions.json")
    rows = [r for r in executions if isinstance(r, dict) and r.get("session_id") == internal_session_pk]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]

    # Sort ascending sequence order as specified
    def _seq(v):
        try:
            return int(v.get("sequence_no"))
        except Exception:
            return 10**18
    rows.sort(key=_seq)

    # Cursor is opaque; implement as base64-encoded integer offset
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            return _err("VALIDATION_ERROR", "Parameter 'cursor' must be a non-empty string when provided.")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if not raw.startswith("offset:"):
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor.")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    total = len(rows)
    page = rows[offset:offset + limit]
    new_offset = offset + len(page)
    has_more = new_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{new_offset}".encode("utf-8")).decode("utf-8")

    return {
        "object": "list",
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def get_repl_output(output_id=None, execution_id=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0512000" if __import__("os").path.isdir("./environment_mix/0512000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                d = json.load(f)
                return d if isinstance(d, list) else []
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _append_request_log(endpoint, status_s, latency_ms, meta=None):
        logs = _load("repl_request_logs.json")
        logs.append({
            "id": "rlog_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status_s,
            "latency_ms": int(latency_ms),
            "timestamp": _iso(_now()),
            "meta": meta or {}
        })
        _save("repl_request_logs.json", logs)

    def _enforce_limits(endpoint):
        logs = _load("repl_request_logs.json")
        now = _now()
        one_min_ago = now - datetime.timedelta(minutes=1)
        day_ago = now - datetime.timedelta(days=1)

        def _parse_ts(s):
            if not isinstance(s, str) or not s:
                return None
            try:
                if s.endswith("Z"):
                    return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        per_min = 0
        per_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != endpoint:
                continue
            ts = _parse_ts(r.get("timestamp"))
            if ts is None:
                continue
            if ts >= one_min_ago:
                per_min += 1
            if ts >= day_ago:
                per_day += 1

        if per_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.", limit_per_minute=120, endpoint=endpoint)
        if per_day >= 5000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", limit_per_day=5000, endpoint=endpoint)
        return None

    endpoint = "get_repl_output"
    t0 = time.time()

    # Relax overly-strict validation: accept either, and if both provided prefer output_id.
    if output_id is None and execution_id is None:
        err = _err("VALIDATION_ERROR", "At least one of 'output_id' or 'execution_id' must be provided.")
        _append_request_log(endpoint, "error", (time.time() - t0) * 1000, {"error": err["error"]})
        return err

    if output_id is not None and (not isinstance(output_id, str) or not output_id.strip()):
        err = _err("VALIDATION_ERROR", "Parameter 'output_id' must be a non-empty string when provided.")
        _append_request_log(endpoint, "error", (time.time() - t0) * 1000, {"error": err["error"]})
        return err
    if execution_id is not None and (not isinstance(execution_id, str) or not execution_id.strip()):
        err = _err("VALIDATION_ERROR", "Parameter 'execution_id' must be a non-empty string when provided.")
        _append_request_log(endpoint, "error", (time.time() - t0) * 1000, {"error": err["error"]})
        return err

    lim_err = _enforce_limits(endpoint)
    if lim_err:
        _append_request_log(endpoint, "error", (time.time() - t0) * 1000, {"error": lim_err["error"]})
        return lim_err

    outputs = _load("repl_outputs.json")
    execs = _load("repl_executions.json")

    out_row = None

    # Prefer output_id when present
    if output_id:
        out_row = next((o for o in outputs if isinstance(o, dict) and o.get("id") == output_id), None)
        if out_row is None and execution_id:
            # try resolving via execution_id if output_id doesn't exist
            out_row = next((o for o in outputs if isinstance(o, dict) and o.get("execution_id") == execution_id), None)

    # Resolve by execution_id if still none
    if out_row is None and execution_id:
        out_row = next((o for o in outputs if isinstance(o, dict) and o.get("execution_id") == execution_id), None)
        if out_row is None:
            ex = next((e for e in execs if isinstance(e, dict) and e.get("id") == execution_id), None)
            if ex is not None:
                ocid = ex.get("output_capture_id")
                if ocid:
                    out_row = next((o for o in outputs if isinstance(o, dict) and o.get("id") == ocid), None)

    if out_row is None:
        err = _err("NOT_FOUND", "Output not found for the provided identifier(s).", output_id=output_id, execution_id=execution_id)
        _append_request_log(endpoint, "error", (time.time() - t0) * 1000, {"error": err["error"]})
        return err

    _append_request_log(endpoint, "ok", (time.time() - t0) * 1000, {"output_id": out_row.get("id"), "execution_id": out_row.get("execution_id")})
    return {"object": "repl_output", "data": out_row}
